import{_ as s,l as o,o as e,c as n,v as r,p as i,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"Saltzer 端到端","description":"","frontmatter":{"title":"Saltzer 端到端","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/saltzer-e2e-paper.md","filePath":"cs/saltzer-e2e-paper.md","lastUpdated":1789023840000}'),c={name:"cs/saltzer-e2e-paper.md"};function E(A,a,_,m,C,f){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="saltzer-端到端" tabindex="-1">Saltzer 端到端 <a class="header-anchor" href="#saltzer-端到端" aria-label="Permalink to &quot;Saltzer 端到端&quot;">​</a></h1><div class="epigraph"><p>功能只应放在端系统能完成且正确的那一层；下层的「几乎正确」不能代替两端的检查。</p><footer>—— Saltzer, Reed and Clark, End-to-End Arguments in System Design, ACM TOCS 1984</footer></div><p><a href="/cs/cerf-kahn-tcp">上一课</a>附录对照了 1974 年互联与可靠流设想。附录对照，不插入主干。主干已在<a href="/cs/layering-e2e">分层与端到端</a>用文件传送例子钉死论证，并在 CRC、TCP 校验、TLS 入口反复引用；这里对照 <strong>1984 原文的问题</strong>：在已有互联的世界上，可靠性、加密、去重该放哪一层。不重画五层图，也不把本篇插回 DMA 之后当第一课网络。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Cerf–Kahn 给出网关与主机协议。Saltzer 等的缺口是设计原则：链路重传挡不住中间内存出错，文件正确性只能在真正读写文件的两端用校验与重试保证。下层努力是性能。原文还谈加密与交付保证的同类结构。主干分层课已经取走这一句；附录对照原文如何用反例把原则写硬。</p><p><span class="marginnote">论证不是「不要 CRC」。主干<a href="/cs/frame-crc">CRC 在帧上</a> 明确：一跳检错降端到端重传频率。反对的是声称下层已经够了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>举文件传送、加密只在链路时换跳即明文、重复报文在中间去重仍可能在端点重复。结论：端到端能做对的功能，规格必须在端。主干<a href="/cs/tls-handshake">TLS</a> 把机密性放到会话两端，正是这条原则在安全课的实例。</p>',8)),(e(),i(h,null,{default:t(()=>[p(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LINK%5B%22%E9%93%BE%E8%B7%AF%E5%B0%BD%E5%8A%9B%22%5D%20--%3E%20PERF%5B%22%E9%99%8D%E4%BD%8E%E9%87%8D%E4%BC%A0%E9%A2%91%E7%8E%87%22%5D%0A%20%20ENDS%5B%22%E7%9C%9F%E6%AD%A3%E4%B8%A4%E7%AB%AF%22%5D%20--%3E%20CORR%5B%22%E6%AD%A3%E7%A1%AE%E6%80%A7%E8%A7%84%E6%A0%BC%22%5D%0A%20%20CORR%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E5%88%86%E5%B1%82%E8%AF%BE%E5%B7%B2%E5%8F%96%E7%94%A8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>原则约束层间合同，使后课不会把 FCS 当成文件完整性，也不会把防火墙当成 TLS。它与 Lampson 矩阵正交：一个谈放哪一层，一个谈谁有权。Codd 下一篇把数据从指针网里抽出来，对象又换。</p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>主干网络第一课必须接 OS 的 DMA 缺口，用教学五层往下走进帧。把 1984 插在 Cerf–Kahn 之后当课序，读者会以为先读论文再碰 MAC。本栏已在分层课取用原则；附录只对照原文论证，不改变「帧在 IP 前」的课序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把端到端与网络中立政策混成一篇。也不要在附录里开主动网络。下一篇对照 Codd 1970 关系模型。</p><p>对照结束应回到主干<a href="/cs/layering-e2e">分层与端到端</a>。1984 文不插入 virtio 与帧之间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Saltzer, Reed and Clark 1984：正确性在真正两端。</li><li>主干分层课已取用；本篇不插入网络课序。</li><li>出处：Saltzer, Reed and Clark, <em>ACM TOCS</em> 1984。</li></ul>',9))])}const u=s(c,[["render",E]]);export{S as __pageData,u as default};
